```{.python .cell-code  code-fold="true" code-summary="LLM evaluation pipeline setup"}
# --- Imports
import os, json, re, time, random, hashlib, pathlib
from collections import deque
from typing import Union, Optional, Dict, Any
import pandas as pd
import numpy as np
from openai import OpenAI

# --- API key and client
key_path = pathlib.Path("key/openai_key.txt")
if os.getenv("OPENAI_API_KEY") is None and key_path.exists():
    os.environ["OPENAI_API_KEY"] = key_path.read_text().strip()
if not os.getenv("OPENAI_API_KEY"):
    raise ValueError("No API key found. Put it in key/openai_key.txt or set OPENAI_API_KEY.")
client = OpenAI()

# --- Model
MODEL = os.getenv("UJ_MODEL", "gpt-5")

# --- File-id cache (content-hash keyed)
FILES_CACHE_PATH = pathlib.Path("cache/file_ids.json")
FILES_CACHE_PATH.parent.mkdir(parents=True, exist_ok=True)
_file_ids: Dict[str, str] = {}
if FILES_CACHE_PATH.exists():
    try:
        _file_ids.update(json.loads(FILES_CACHE_PATH.read_text()))
    except Exception:
        _file_ids = {}

def _sha256_of_file(p: pathlib.Path) -> str:
    h = hashlib.sha256()
    with open(p, "rb") as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

def _get_file_id(pdf_path: Union[str, pathlib.Path]) -> str:
    p = pathlib.Path(pdf_path)
    if not p.exists():
        raise FileNotFoundError(f"File not found: {p}")
    key = _sha256_of_file(p)
    if key in _file_ids:
        fid = _file_ids[key]
        try:
            client.files.retrieve(fid)
            return fid
        except Exception:
            pass  # stale id → re-upload
    with open(p, "rb") as fh:
        up = client.files.create(file=fh, purpose="assistants")
    _file_ids[key] = up.id
    FILES_CACHE_PATH.write_text(json.dumps(_file_ids, ensure_ascii=False, indent=2))
    return up.id

# --- Rate pacer (TPM + RPM)
class TokenPacer:
    def __init__(self, tpm_limit=30000, rpm_limit=50, safety=0.9, warmup_est=8000):
        self.tpm = int(tpm_limit * safety)
        self.rpm = int(rpm_limit * safety)
        self.token_events = deque()
        self.call_events = deque()
        self.est = warmup_est
    def _purge(self):
        now = time.time()
        while self.token_events and now - self.token_events[0][0] > 60:
            self.token_events.popleft()
        while self.call_events and now - self.call_events[0][0] > 60:
            self.call_events.popleft()
    def before(self, est_tokens=None):
        est = self.est if est_tokens is None else est_tokens
        self._purge()
        now = time.time()
        used_tokens = sum(t for _, t in self.token_events)
        need_sleep = 0.0
        if used_tokens + est > self.tpm and self.token_events:
            need_sleep = max(need_sleep, 60 - (now - self.token_events[0][0]))
        if len(self.call_events) + 1 > self.rpm and self.call_events:
            need_sleep = max(need_sleep, 60 - (now - self.call_events[0][0]))
        if need_sleep > 0:
            time.sleep(need_sleep + random.random() * 0.3)
    def after(self, resp):
        self._purge()
        self.call_events.append((time.time(),))
        d = _resp_as_dict(resp)
        u = d.get("usage") or {}
        tok = (u.get("input_tokens") or 0) + (u.get("output_tokens") or 0)
        od = (u.get("output_tokens_details") or {})
        tok += od.get("reasoning_tokens") or 0
        self.token_events.append((time.time(), tok))
        self.est = max(1000, 0.5 * self.est + 0.5 * tok)
        return tok

PACER = TokenPacer(
    tpm_limit=int(os.getenv("UJ_TPM", "30000")),
    rpm_limit=int(os.getenv("UJ_RPM", "50")),
    safety=0.9,
    warmup_est=8000,
)

def _sleep_from_429_text(msg: str, base=3.0) -> float:
    m = re.search(r"try again in ([0-9.]+)s", msg, flags=re.I)
    return (float(m.group(1)) if m else base) + random.random() * 0.5

def call_with_retries(make_call, max_tries=6):
    delay = 2.0
    for _ in range(max_tries):
        PACER.before()
        try:
            resp = make_call()
            PACER.after(resp)
            return resp
        except Exception as e:
            s = str(e).lower()
            if "rate limit" in s or "429" in s or "tpm" in s:
                time.sleep(_sleep_from_429_text(str(e), base=delay))
                delay = min(delay * 1.7, 20.0)
                continue
            if any(t in s for t in ("timeout", "service unavailable", "gateway", "overloaded")):
                time.sleep(delay + random.random() * 0.5)
                delay = min(delay * 1.7, 20.0)
                continue
            raise
    raise RuntimeError("Too many retries.")

# --- Responses helpers
def _resp_as_dict(resp) -> Dict[str, Any]:
    try:
        return resp.model_dump()
    except Exception:
        pass
    try:
        return resp.to_dict()
    except Exception:
        pass
    if isinstance(resp, dict):
        return resp
    return {}

def _get_output_text(resp) -> str:
    try:
        t = getattr(resp, "output_text", None)
        if t:
            return t
    except Exception:
        pass
    d = _resp_as_dict(resp)
    if not d:
        return ""
    if d.get("output_text"):
        return d["output_text"]
    parts = []
    for item in d.get("output", []) or []:
        if item.get("type") == "message":
            for c in item.get("content") or []:
                txt = c.get("text")
                if txt:
                    parts.append(txt)
    return "".join(parts).strip()

def _strip_code_fences(s: str) -> str:
    if "```" not in s:
        return s
    first = s.find("```")
    if first == -1:
        return s
    second = s.find("```", first + 3)
    if second == -1:
        return s
    inner = s[first + 3:second]
    return re.sub(r"^\s*json\r?\n", "", inner, flags=re.I)

def _extract_json(s: str) -> Dict[str, Any]:
    try:
        return json.loads(s)
    except Exception:
        pass
    s2 = _strip_code_fences(s).strip()
    start = s2.find("{")
    if start == -1:
        raise ValueError("No JSON object start found.")
    depth = 0
    in_str = False
    esc = False
    for i in range(start, len(s2)):
        ch = s2[i]
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
        else:
            if ch == '"':
                in_str = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    candidate = s2[start:i+1]
                    return json.loads(candidate)
    raise ValueError("Unterminated JSON object in model output.")

```
:::




We enforce a JSON Schema for the results. The model must return one object for each of the named criteria including a midpoint rating and a 90% interval for each, as well as a short rationale for each rating. This guarantees that every paper is scored on the same fields with the same types and bounds. It makes the analysis reproducible and comparisons clean. 

We request credible intervals (as we do for human evaluators) to allow the model to communicate its uncertainty rather than suggest false precision; these can also be incorporated into our metrics, penalizing a model's inaccuracy more when it's stated with high confidence

We request brief rationales to allow the LLM to clarify the evidence and the process that drove it's rating. This could help us understand it's prioritization and taste, and might help us spot if it misunderstood our instructions. However, we cannot be confident that it's response to this question accurate reveals the process or the reasoning steps behind the ratings. E.g., this might reflect an ex-post attempt to construct a concise and believable story, when in fact the process that may have been far more random, too complicated to discuss in words, or reflecting biases.  



::: {.cell}

```{.python .cell-code  code-fold="true" code-summary="Schema, prompt, evaluator"}
# --- Metrics and schema
METRICS = [
    "overall",
    "claims_evidence",
    "methods",
    "advancing_knowledge",
    "logic_communication",
    "open_science",
    "global_relevance",
]

metric_schema = {
    "type": "object",
    "properties": {
        "midpoint": {"type": "number", "minimum": 0, "maximum": 100},
        "lower_bound": {"type": "number", "minimum": 0, "maximum": 100},
        "upper_bound": {"type": "number", "minimum": 0, "maximum": 100},
        "rationale": {"type": "string", "maxLength": 400},
    },
    "required": ["midpoint", "lower_bound", "upper_bound", "rationale"],
    "additionalProperties": False,
}

TIER_METRIC_SCHEMA = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "score": {"type": "number", "minimum": 0, "maximum": 5},
        "ci_lower": {"type": "number", "minimum": 0, "maximum": 5},
        "ci_upper": {"type": "number", "minimum": 0, "maximum": 5},
        "rationale": {"type": "string", "maxLength": 400},
    },
    "required": ["score", "ci_lower", "ci_upper", "rationale"],
}

COMBINED_SCHEMA = {
    "type": "object",
    "properties": {
        "metrics": {
            "type": "object",
            "properties": {
                **{m: metric_schema for m in METRICS},
                "tier_should": TIER_METRIC_SCHEMA,
                "tier_will": TIER_METRIC_SCHEMA,
            },
            "required": METRICS + ["tier_should", "tier_will"],
            "additionalProperties": False,
        }
    },
    "required": ["metrics"],
    "additionalProperties": False,
}

TEXT_FORMAT_COMBINED = {
    "type": "json_schema",
    "name": "paper_assessment_with_tiers_v1",
    "strict": True,
    "schema": COMBINED_SCHEMA,
}

# --- System prompt (long but cleaned; field names aligned)
_METRICS_TXT = "\n  " + "\n  ".join(METRICS) + "\n"

SYSTEM_PROMPT_COMBINED = f"""
Your role — You are an academic expert and practitioner across relevant fields. Act as an expert research evaluator.

You will provide quantitative metrics. For each metric you will give a best-guess value and a 90% credible interval.

### Percentile rankings relative to a reference group
For several questions, provide a **percentile ranking** from 0–100. This means “what proportion of papers in the reference group are worse than this paper, by this criterion”. 100 = best in group, 50 = median, 0 = worst.

**Reference group.** Use serious recent work in the same area that you have encountered in the last three years. If this work belongs to an applied/policy stream, compare it to applied/policy research aimed at a similar audience with similar goals.

**What counts as “serious” research?** Research by trained professionals with time and resources to devote months or years to a project, typically working papers and seminar drafts produced in academia or credible research institutions.

**What counts as the “same area”?** Consider field and subfield; whether similar methods would address similar questions; and closeness of the substantive question. If the topic is very niche, broaden the group appropriately.

**Comparability across evaluators.** If your exposure is skewed to especially high or low quality work, adjust your implicit reference group to maintain comparability.

### Midpoint rating and credible intervals
For each percentile metric, provide:
- a **midpoint** (the median of your belief distribution for the true value), and
- a **90% credible interval** (the narrowest interval you judge has 90% probability of containing the true value).

Being well calibrated means your 90% intervals contain the true value about 90% of the time.

### Category interpretations

**Overall assessment** — Heuristic judgment of quality, credibility, importance for impactful applied research, and practical usefulness.

**Claims, strength and characterization of evidence** — Are main questions and claims clear? Is the evidence strong and appropriately characterized?

**Methods: justification, reasonableness, validity, robustness** — Are methods well‑justified and explained? Are assumptions reasonable? Are results robust to reasonable changes? Have authors taken steps to avoid bias and questionable research practices (e.g., preregistration, multiplicity control, full reporting)?

**Advancing knowledge and practice** — Contribution to the field and especially to practice relevant to global priorities and impactful interventions. Reward rigorous applications that produce useful insights. Sound, well‑presented null results are valuable.

**Logic and communication** — Clarity of goals and definitions; transparent reasoning and assumptions; logical correctness; conclusions consistent with evidence; figures/tables clear and relevant.

**Open, collaborative, replicable research** — Reproducibility and clarity for replication; data availability and integrity; internal consistency; provision of useful building blocks (tools, data, resources).

**Relevance to global priorities, usefulness for practitioners** — Practical relevance and policy realism; useful quantified estimates where possible (effects, costs, benefits); communication accessible to decision‑makers without misleading simplification.

### Journal ranking tiers (0.0–5.0)
Provide two assessments on a continuous 0–5 scale (decimals allowed), each with a 90% credible interval:

1) **tier_should** — Where this work **should** be published if the process were fair, unbiased, and aligned to the category metrics above.

2) **tier_will** — Where this work **will** likely be published given real‑world processes.

Scale anchors:
- **0/5**: Won’t publish / little to no value.
- **1/5**: OK / somewhat valuable journal.
- **2/5**: Marginal B‑journal / decent field journal.
- **3/5**: Top B‑journal / strong field journal.
- **4/5**: Marginal A‑journal / top field journal.
- **5/5**: A‑journal / top general journal.

Use non‑integer scores when appropriate (e.g., 4.6 or 2.2). Example: if there is an 80% chance of a marginal B‑journal and a 20% chance of a top B‑journal, a reasonable point estimate is 2.2.

If the work is already published and you know where, report the **prediction you would have made absent that knowledge**.

### Output format and constraints
Return **STRICT JSON** matching the supplied schema. **No preamble. No markdown. No extra text.**

Fill every key in the object `metrics`:

{_METRICS_TXT}
Plus `tier_should` and `tier_will`.

**Field names**
- **Percentile metrics** → `midpoint`, `lower_bound`, `upper_bound`, `rationale` (≤400 chars).
- **Tier metrics** → `score`, `ci_lower`, `ci_upper`, `rationale` (≤400 chars).

**Bounds**
- Percentiles in [0, 100].
- Tiers in [0, 5].

Be specific and terse in rationales. Do not include citations or external URLs. Do not refer to these instructions. Output the JSON object only.
""".strip()

# --- Meta extraction
def _reasoning_meta(resp) -> Dict[str, Any]:
    d = _resp_as_dict(resp)
    rid, summary_text = None, None
    out = d.get("output") or []
    if out and isinstance(out, list) and out[0].get("type") == "reasoning":
        rid = out[0].get("id")
        summ = out[0].get("summary") or []
        if summ and isinstance(summ, list):
            summary_text = summ[0].get("text")
    usage = d.get("usage") or {}
    odet  = usage.get("output_tokens_details") or {}
    return {
        "response_id": d.get("id"),
        "reasoning_id": rid,
        "reasoning_summary": summary_text,
        "input_tokens": usage.get("input_tokens"),
        "output_tokens": usage.get("output_tokens"),
        "reasoning_tokens": odet.get("reasoning_tokens"),
    }

# --- Core evaluator
def evaluate_paper(pdf_path: Union[str, pathlib.Path],
                   model: Optional[str] = None,
                   use_reasoning: bool = True,
                   parse_retry: int = 1) -> Dict[str, Any]:
    """Upload the PDF and get structured JSON per COMBINED_SCHEMA."""
    model = model or MODEL
    fid = _get_file_id(pdf_path)

    def _payload():
        payload = dict(
            model=model,
            text={"format": TEXT_FORMAT_COMBINED},
            input=[
                {"role": "system", "content": [
                    {"type": "input_text", "text": SYSTEM_PROMPT_COMBINED}
                ]},
                {"role": "user", "content": [
                    {"type": "input_file", "file_id": fid},
                    {"type": "input_text", "text": "Return STRICT JSON per schema. No extra text."}
                ]},
            ],
            max_output_tokens=2000,
            store=False,
        )
        if use_reasoning:
            payload["reasoning"] = {"effort": "medium", "summary": "auto"}
        return payload

    def _make_call():
        return client.responses.create(**_payload())

    # First attempt
    resp = call_with_retries(_make_call)
    text = _get_output_text(resp)
    try:
        out = _extract_json(text)
    except Exception:
        if parse_retry <= 0:
            raise
        # One more attempt with a stricter nudge
        def _make_call_2():
            payload = _payload()
            payload["input"][-1]["content"].append(
                {"type": "input_text", "text": "Output a single JSON object only. No markdown. No explanation."}
            )
            return client.responses.create(**payload)
        resp = call_with_retries(_make_call_2)
        text = _get_output_text(resp)
        out = _extract_json(text)

    meta = _reasoning_meta(resp)
    return {**out, **meta}

```
:::



We use a single‑step call with a reasoning model that supports file input. One step avoids hand‑offs and summary loss from a separate "ingestion" stage. The model reads the whole PDF and produces the JSON defined above. We do not retrieve external sources or cross‑paper material for these scores; the evaluation is anchored in the manuscript itself.



::: {.cell}

