                "hi":          vals.get("ci_upper"),
                "rationale":   vals.get("rationale"),
                "scale_min":   0,
                "scale_max":   5,
            })
        else:
            rows.append({
                "paper":       paper_id,
                "metric":      metric,
                "metric_type": "percentile",
                "value":       vals.get("midpoint"),
                "lo":          vals.get("lower_bound"),
                "hi":          vals.get("upper_bound"),
                "rationale":   vals.get("rationale"),
                "scale_min":   0,
                "scale_max":   100,
            })

